package verbs

func coordinateVerbs() []*verb {
	return []*verb{
		{name: "stream add", group: "coordinate", role: roleCoordinator, usage: "<s> --repo <org/repo> [--base main] [--mode auto|group|hand] [--forge github]", flags: "repo= base= mode= forge=", min: 1, max: 1, run: runStreamAdd,
			about: "adds a stream: its repository, base branch, landing mode (auto by default) and forge (none: no PR or CI, landed by hand)",
			needs: []string{"the stream exists: nova-sprint show <s>", "the base branch is not at origin: push it, or pass --base"}},
		{name: "stream set", group: "coordinate", role: roleCoordinator, usage: "<s> [--mode auto|group|hand] [--forge github|none]", flags: "mode= forge=", min: 1, max: 1, run: runStreamSet,
			about: "changes a stream's landing mode or forge",
			needs: []string{"an unknown stream: nova-sprint stream add <s> --repo <org/repo>"}},
		{name: "add", group: "coordinate", role: roleCoordinator, usage: "--stream <s> --brief-file <f>... [--needs <a,b>] [--after <a,b>] [--priority <level>] [--dry-run] | --stream <s> --sentinel <id> --needs <a,b>", flags: "stream= brief-file=* needs= after= priority= sentinel= dry-run", max: 0, run: runAdd,
			about: "adds producers from briefs that pass the card contract, or a sentinel that lands when its needs land",
			needs: []string{"an unknown stream: nova-sprint stream add", "a brief missing a contract section, by name", "an unknown need, or a cycle, named"}},
		{name: "judge", group: "coordinate", role: roleCoordinator, usage: "[<judgement> <choice> --reason <why> [--card <id>]] | <group> <choice> --expect <n> --reason <why>", flags: "reason= expect= card=", max: 2, run: runJudge,
			about: "lists the open judgements, or answers one (or a group) with one of its offered choices",
			needs: []string{"not open: names who closed it", "a choice it does not offer: lists them", "a group that changed: --expect <its size now>"}},
		{name: "land", group: "coordinate", role: roleCoordinator, usage: "<card|stream> --reason <why> [--head <sha>]", flags: "reason= head=", min: 1, max: 1, run: runLand,
			about: "the coordinator's hand landing after looking (rung 3): a card's PR into its base merged and the card landed; a stream's group PR merged and every merging card whose head is in the base landed",
			needs: []string{"the head is not on origin: the worker pushes it", "the base moved under it or the merge was refused: said verbatim"}},
		{name: "hold", group: "coordinate", role: roleCoordinator, usage: "<row|stream>... --reason <why> [--dry-run]", flags: "reason= dry-run", min: 1, max: -1, run: runHold,
			about: "stops deals to a row, or parks a stream's ready producers"},
		{name: "unhold", group: "coordinate", role: roleCoordinator, usage: "<row|stream>... --reason <why> [--dry-run]", flags: "reason= dry-run", min: 1, max: -1, run: runHold,
			about: "ends a hold"},
		{name: "priority", group: "coordinate", role: roleCoordinator, usage: "<card> low|normal|high|critical|blocker --reason <why>", flags: "reason=", min: 2, max: 2, run: runPriority,
			about: "sets a producer's level",
			needs: []string{"a consumer id: its producer's id", "a final card"}},
		{name: "drop", group: "coordinate", role: roleCoordinator, usage: "<card>... --reason <why> [--waive <dependant>]... [--relink <dependant>=<card>]... [--dry-run]", flags: "reason= waive=* relink=* dry-run", min: 1, max: -1, run: runDrop,
			about: "fails producers that should not be done; each dependant is waived, relinked, or fails with it",
			needs: []string{"a live consumer: its holder's release", "an open judgement on it: nova-sprint judge <j> drop"}},
		{name: "relink", group: "coordinate", role: roleCoordinator, usage: "<card> --need <failed need> --to <card> --reason <why>", flags: "need= to= reason=", min: 1, max: 1, run: runRelink,
			about: "points a dependant's failed need at another card"},
		{name: "replace", group: "coordinate", role: roleCoordinator, usage: "<card> --by <card> --reason <why> [--waive <dependant>]... [--relink <dependant>=<card>]... [--dry-run]", flags: "by= reason= waive=* relink=* dry-run", min: 1, max: 1, run: runDrop,
			about: "fails a producer in favour of another; its dependants follow the other"},
		{name: "policy set", group: "coordinate", role: roleCoordinator, usage: "<file> --reason <why>", flags: "reason=", min: 1, max: 1, run: runPolicy,
			about: "checks and stores a policy file as the next version, not active"},
		{name: "policy activate", group: "coordinate", role: roleCoordinator, usage: "<version> --reason <why>", flags: "reason=", min: 1, max: 1, run: runPolicy,
			about: "makes a stored version the active one"},
		{name: "policy show", group: "coordinate", role: roleWorker, usage: "[<version>] [--list]", flags: "list", max: 1, run: runPolicy,
			about: "a version's source, or every version"},
		{name: "policy diff", group: "coordinate", role: roleWorker, usage: "<version|default> [<version|default>]", min: 1, max: 2, run: runPolicy,
			about: "the difference between two versions"},
		{name: "policy check", group: "coordinate", role: roleWorker, usage: "<file|version>", min: 1, max: 1, run: runPolicy,
			about: "every answer a version or file would change, and every refusal"},
	}
}

func operateVerbs() []*verb {
	return []*verb{
		{name: "run", group: "operate", usage: "[--listen <addr>]", flags: "listen=", max: 0, run: runRun,
			about: "the one chooser: the service up installs; deals, reads and lands",
			needs: []string{"another run chooses: names its host and pid", "sprint is hooked elsewhere"}},
		{name: "worker", group: "operate", usage: "--as <row> --work-clone <dir> --coordinator-hosts <h,h> [--host <h>] [--root <dir>] [--state-dir <dir>] [--harness claude|codex|opencode] [--mirror <dir>] [--origin <url>] [--provider-upstream <url> --provider-hosts <h,h> --provider-key <name>] [--once]", flags: "host= root= state-dir= harness= work-clone= mirror= origin= coordinator-hosts= provider-upstream= provider-hosts= provider-key= once", max: 0, run: runWorker,
			about: "a bench's runner (nova-worker): hooks its row, takes what is dealt, runs it, reports"},
		{name: "dash", group: "operate", usage: "--listen <addr> [--pull <url>]", flags: "listen= pull=", max: 0, run: runDash,
			about: "serves the board from the store, or a pulled copy of run's on a public host"},
		{name: "stop", group: "operate", role: roleCoordinator, usage: "--reason <why>", flags: "reason=", max: 0, run: runStop,
			about: "stops the tick: nothing is dealt, read or landed until start; verbs still work"},
		{name: "start", group: "operate", role: roleCoordinator, usage: "[--reason <why>]", flags: "reason=", max: 0, run: runStop,
			about: "starts the tick again"},
		{name: "backup", group: "operate", role: roleCoordinator, usage: "[--out <dir>]", flags: "out=", max: 0, run: runBackup,
			about: "a verified dump of the store",
			needs: []string{"pg_dump missing or older than the server"}},
		{name: "restore", group: "operate", usage: "<file> --as <coordinator>", min: 1, max: 1, run: runRestore,
			about: "loads a verified dump into an empty store and hooks you in as coordinator; the same dump again only hooks",
			needs: []string{"a run holds the lock: stop it", "the store holds another dump's data: nova-sprint clear first"}},
		{name: "clear", group: "operate", role: roleCoordinator, usage: "--confirm <epoch> [--dry-run]", flags: "confirm= dry-run", max: 0, run: runClear,
			about: "ends the epoch after a verified backup; every card goes",
			needs: []string{"a wrong epoch: --confirm <the current one>", "a live consumer: its release"}},
	}
}
